      expect(find.text('Page 2'), findsOneWidget);
      expect(tester.takeException(), isNull);
    },
    variant: TargetPlatformVariant.only(TargetPlatform.android),
  );
  testWidgets(
    'camera error preserves gallery action and existing pages',
    (tester) async {
      messenger.setMockMethodCallHandler(camera, (call) async {
        if (call.method == 'capture') {
          throw PlatformException(
            code: 'camera',
            message: 'Choose gallery images instead.',
          );
        }
        return ['/tmp/one.jpg'];
      });
      await tester.pumpWidget(
        const ProviderScope(child: MaterialApp(home: ScanPdfScreen())),
      );
      await tester.pumpAndSettle();
      await tester.tap(find.text('Scan'));
      await tester.pumpAndSettle();
      expect(find.text('Choose gallery images instead.'), findsOneWidget);
      expect(find.byTooltip('Choose gallery images'), findsOneWidget);
      expect(find.text('Page 1'), findsOneWidget);
      expect(tester.takeException(), isNull);
    },
    variant: TargetPlatformVariant.only(TargetPlatform.android),
  );
  testWidgets('export sheet cancellation leaves draft intact and higher quality reaches native export', (tester) async {
    var cleared = false;
    MethodCall? export;
    messenger.setMockMethodCallHandler(camera, (call) async {
      if (call.method == 'clear') cleared = true;
      return ['/tmp/draft.jpg'];
    });
    messenger.setMockMethodCallHandler(pdf, (call) async {
      export = call;
      throw PlatformException(code: 'storage', message: 'Not enough space');
    });
    await tester.pumpWidget(const ProviderScope(child: MaterialApp(home: ScanPdfScreen())));
    await tester.pumpAndSettle();
    await tester.tap(find.text('Save PDF'));
    await tester.pumpAndSettle();
    await tester.tapAt(const Offset(10, 10));
    await tester.pumpAndSettle();
    expect(export, isNull);
    expect(cleared, isFalse);
    await tester.tap(find.text('Save PDF'));
    await tester.pumpAndSettle();
    await tester.tap(find.text('A4'));
    await tester.pumpAndSettle();
    await tester.tap(find.text('US Letter').last);
    await tester.pumpAndSettle();
    await tester.tap(find.text('Match each page'));
    await tester.pumpAndSettle();
    await tester.tap(find.text('Landscape').last);
    await tester.pumpAndSettle();
    await tester.ensureVisible(find.text('Higher quality'));
    await tester.tap(find.text('Higher quality'));
    await tester.pump();
    await tester.ensureVisible(find.text('Export PDF'));
        await tester.tap(find.text('Export PDF'));
    await tester.pumpAndSettle();
    expect(export?.method, 'imagesToPdf');
    expect(export?.arguments['scanDraft'], isTrue);
