import 'dart:async';
import 'dart:convert';
import 'dart:typed_data';
import 'dart:math' as math;

import 'package:flutter/material.dart';
import 'package:flutter/gestures.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

import '../../../core/widgets/common.dart';
import '../data/pdf_studio_repository.dart';
import '../data/studio_file_item.dart';
import '../data/studio_pdf_engine.dart';
import 'studio_operation.dart';

enum _MarkTool {
  select,
  arrow,
  note,
  ink,
  highlight,
  underline,
  strike,
  rectangle,
  circle,
  text,
  signature,
}

class StudioAnnotationScreen extends ConsumerStatefulWidget {
  const StudioAnnotationScreen({super.key, required this.file});
  final StudioFileItem file;

  @override
  ConsumerState<StudioAnnotationScreen> createState() =>
      _StudioAnnotationScreenState();
}

class _StudioAnnotationScreenState
    extends ConsumerState<StudioAnnotationScreen> {
  Map<String, List<Map<String, dynamic>>> _all = {};
  ({Uint8List bytes, int width, int height})? _image;
  final _pending = <Offset>[];
  int _page = 1;
  int _total = 0;
  int _color = 0xFF087F76;
  double _opacity = 1;
  bool _collapsed = false, _moveRecorded = false;
  final _undo = <int, List<List<Map<String, dynamic>>>>{};
  final _redo = <int, List<List<Map<String, dynamic>>>>{};
  Map<String, List<Map<String, dynamic>>> _initial = {};
  static final _writesByPath = <String, Future<void>>{};
  int _pendingWrites = 0;
  bool _saveError = false, _hasSaved = false;
  bool get _ready => !_working && _image != null && _total > 0;
  double _stroke = 3;
  _MarkTool _tool = _MarkTool.ink;
  bool _working = true;
  int? _selected;
  Offset? _dragPoint;

  void _selectMark(Offset point) {
    _selected = null;
    for (var i = _marks.length - 1; i >= 0; i--) {
      final raw = _marks[i]['points'] as List? ?? const [];
      final points = [
        for (final p in raw)
          if (p is List && p.length == 2)
            Offset((p[0] as num).toDouble(), (p[1] as num).toDouble()),
      ];
      if (points.isEmpty) continue;
      final left =
          points.map((p) => p.dx).reduce((a, b) => a < b ? a : b) - .04;
      final top = points.map((p) => p.dy).reduce((a, b) => a < b ? a : b) - .04;
      final right =
          points.map((p) => p.dx).reduce((a, b) => a > b ? a : b) + .15;
      final bottom =
          points.map((p) => p.dy).reduce((a, b) => a > b ? a : b) + .05;
      if (Rect.fromLTRB(left, top, right, bottom).contains(point)) {
        _selected = i;
        break;
      }
    }
  }

  List<Map<String, dynamic>> get _marks => _all.putIfAbsent('$_page', () => []);

  List<Map<String, dynamic>> _copyMarks(List<Map<String, dynamic>> marks) =>
      (jsonDecode(jsonEncode(marks)) as List).map((m) => Map<String, dynamic>.from(m as Map)).toList();
  Map<String, List<Map<String, dynamic>>> _copyPages(Map<String, List<Map<String, dynamic>>> pages) =>
      {for (final e in pages.entries) e.key: _copyMarks(e.value)};
  void _checkpoint() {
    final stack = _undo.putIfAbsent(_page, () => []);
    stack.add(_copyMarks(_marks));
    if (stack.length > 20) stack.removeAt(0);
    _redo.remove(_page);
  }
  void _history(bool forward) {
    if (!_ready) return;
    final from = (forward ? _redo : _undo)[_page];
    if (from == null || from.isEmpty) return;
    setState(() {
      (forward ? _undo : _redo).putIfAbsent(_page, () => []).add(_copyMarks(_marks));
      _all['$_page'] = from.removeLast();
      _selected = null; _pending.clear();
    });
    unawaited(_persist());
  }
  void _deleteSelected() {
    if (!_ready || _selected == null || _selected! >= _marks.length) return;
    setState(() { _checkpoint(); _marks.removeAt(_selected!); _selected = null; });
    unawaited(_persist());
  }
  void _choose(_MarkTool tool) => setState(() {
    _tool = tool; _selected = null; _pending.clear();
    _opacity = tool == _MarkTool.highlight ? .35 : 1;
  });
  String _toolLabel(_MarkTool tool) => switch(tool) {
    _MarkTool.select => 'Select / move', _MarkTool.ink => 'Pen', _MarkTool.highlight => 'Highlight',
    _MarkTool.strike => 'Strike through', _MarkTool.signature => 'Typed signature',
    _MarkTool.arrow => 'Arrow', _MarkTool.note => 'Note', _MarkTool.underline => 'Underline',
    _MarkTool.rectangle => 'Rectangle', _MarkTool.circle => 'Circle', _MarkTool.text => 'Text',
  };
  IconData _toolIcon(_MarkTool tool) => switch(tool) {
    _MarkTool.select => Icons.near_me_outlined, _MarkTool.ink => Icons.edit_outlined,
    _MarkTool.highlight => Icons.highlight_outlined, _MarkTool.text => Icons.text_fields,
    _MarkTool.arrow => Icons.north_east, _MarkTool.note => Icons.sticky_note_2_outlined,
    _MarkTool.underline => Icons.format_underlined, _MarkTool.strike => Icons.format_strikethrough,
    _MarkTool.rectangle => Icons.rectangle_outlined, _MarkTool.circle => Icons.circle_outlined,
    _MarkTool.signature => Icons.draw_outlined,
  };
  Future<void> _tools() async {
    await showModalBottomSheet<void>(context: context, isScrollControlled: true, showDragHandle: true, builder: (sheet) => SafeArea(child: SingleChildScrollView(padding: const EdgeInsets.fromLTRB(20,0,20,24), child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
      Text('Annotation tools', style: Theme.of(sheet).textTheme.titleLarge),
      const SizedBox(height: 12),
      for (final group in <String, List<_MarkTool>>{
        'Navigate': [_MarkTool.select],
        'Markup': [_MarkTool.ink, _MarkTool.highlight, _MarkTool.underline, _MarkTool.strike],
        'Shapes': [_MarkTool.arrow, _MarkTool.rectangle, _MarkTool.circle],
        'Notes': [_MarkTool.note, _MarkTool.text, _MarkTool.signature],
      }.entries) ...[
        Padding(padding: const EdgeInsets.symmetric(vertical: 10), child: Text(group.key, style: Theme.of(sheet).textTheme.titleSmall)),
        Wrap(spacing: 8, runSpacing: 8, children: [for (final tool in group.value) ChoiceChip(avatar: Icon(_toolIcon(tool), size: 18), label: Text(_toolLabel(tool)), selected: _tool == tool, onSelected: (_) { _choose(tool); Navigator.pop(sheet); })]),
      ],
      const SizedBox(height: 16), const Text('Typed signatures are visual annotations, not certified digital signatures.'),
    ]))));
  }
  Future<void> _style() async {
    await showModalBottomSheet<void>(context: context, isScrollControlled: true, showDragHandle: true, builder: (sheet) => StatefulBuilder(builder: (sheet, update) => SafeArea(child: SingleChildScrollView(padding: const EdgeInsets.fromLTRB(20,0,20,24), child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
      Text('Style for new marks', style: Theme.of(sheet).textTheme.titleLarge), const SizedBox(height: 8),
      const Text('Changes apply to the next mark. Select / move keeps existing marks unchanged.'), const SizedBox(height: 12),
      Wrap(spacing: 6, children: [for (final entry in <String,int>{'Teal':0xFF087F76,'Purple':0xFF6D35D4,'Rose':0xFFEF4978,'Gold':0xFFE59A22,'Slate':0xFF18203B}.entries) IconButton(tooltip: '${entry.key} ink', onPressed: () { setState(() => _color = entry.value); update(() {}); }, icon: Icon(_color == entry.value ? Icons.check_circle : Icons.circle_outlined, color: Color(entry.value)))]),
      Text('Stroke size: ${_stroke.toStringAsFixed(0)}'), Slider(semanticFormatterCallback: (v) => 'Stroke size ${v.round()}', value: _stroke, min: 1, max: 10, divisions: 9, onChanged: (v) { setState(() => _stroke = v); update(() {}); }),
      Text('Opacity: ${(_opacity*100).round()}%'), Slider(semanticFormatterCallback: (v) => 'Opacity ${(v*100).round()} percent', value: _opacity, min: .1, max: 1, divisions: 18, onChanged: (v) { setState(() => _opacity = v); update(() {}); }),
      const SizedBox(height: 8), Align(alignment: Alignment.centerRight, child: FilledButton(onPressed: () => Navigator.pop(sheet), child: const Text('Done'))),
    ])))));
  }
  Future<void> _discardSession() async {
    final confirmed = await showDialog<bool>(context: context, builder: (dialog) => AlertDialog(title: const Text('Discard session edits?'), content: const Text('Restore the annotation layer from when this editor opened. Earlier annotations and the original PDF stay intact.'), actions: [TextButton(onPressed: () => Navigator.pop(dialog,false), child: const Text('Keep editing')), FilledButton(onPressed: () => Navigator.pop(dialog,true), child: const Text('Restore earlier layer'))]));
    if (confirmed != true || !mounted) return;
    setState(() { _all = _copyPages(_initial); _undo.clear(); _redo.clear(); _selected = null; _pending.clear(); });
    await _persist();
  }
  Widget _dock() {
    final theme = Theme.of(context);
    return Padding(padding: const EdgeInsets.fromLTRB(12,6,12,6), child: Material(elevation: 3, shadowColor: theme.colorScheme.primary.withValues(alpha: .08), color: theme.colorScheme.surface, borderRadius: BorderRadius.circular(24), clipBehavior: Clip.antiAlias, child: _collapsed
      ? InkWell(onTap: _ready ? () => setState(() => _collapsed = false) : null, child: Padding(padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 14), child: Row(mainAxisSize: MainAxisSize.min, children: [Icon(_toolIcon(_tool), size: 20), const SizedBox(width: 8), Flexible(child: Text('Page $_page / $_total · ${_toolLabel(_tool)}')), const SizedBox(width: 8), const Icon(Icons.expand_less)])))
      : Padding(padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4), child: Column(mainAxisSize: MainAxisSize.min, children: [
        Row(mainAxisAlignment: MainAxisAlignment.spaceEvenly, children: [for (final tool in [_MarkTool.select,_MarkTool.ink,_MarkTool.highlight,_MarkTool.text]) IconButton(tooltip: _toolLabel(tool), isSelected: _tool == tool, onPressed: _ready ? () => _choose(tool) : null, icon: Icon(_toolIcon(tool))), IconButton(tooltip: 'More annotation tools', onPressed: _ready ? _tools : null, icon: const Icon(Icons.more_horiz))]),
        Row(children: [IconButton(tooltip: 'Annotation style', onPressed: _ready ? _style : null, icon: Icon(Icons.tune, color: Color(_color))), Expanded(child: Text(_pendingWrites > 0 ? 'Saving edits…' : _saveError ? 'Edits not saved · retry Save' : '${_toolLabel(_tool)} · ${(_opacity*100).round()}%${_hasSaved ? ' · Saved' : ''}', maxLines: 2, style: theme.textTheme.labelSmall)), IconButton(tooltip: 'Collapse editing tools', onPressed: _ready ? () => setState(() => _collapsed = true) : null, icon: const Icon(Icons.expand_more))]),
      ]))));
  }

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) => _load());
  }

  Future<void> _load() async {
    try {
      await (_writesByPath[widget.file.editStateJsonPath] ?? Future<void>.value());
      final results = await Future.wait<dynamic>([
        StudioPdfEngine.pageCount(widget.file.internalFilePath),
        StudioPdfEngine.readAnnotations(widget.file.editStateJsonPath),
      ]);
      _all = results[1] as Map<String, List<Map<String, dynamic>>>;
      _total = results[0] as int;
      if (_total <= 0) throw const FormatException('Document has no readable pages.');
      _initial = _copyPages(_all);
      await _showPage();
    } catch (e) {
      if (mounted) {
        setState(() => _working = false);
        showHSnack(
          context,
          'Annotation editor could not open: $e',
          error: true,
        );
      }
    }
  }

  Future<void> _showPage() async {
    if (mounted) setState(() { _working = true; _image = null; });
    try {
      _selected = null;
      final result = await StudioPdfEngine.renderPage(
        widget.file.internalFilePath,
        _page - 1,
      );
      if (mounted) {
        setState(() {
          _image = (
            bytes: result.bytes,
            width: result.width,
            height: result.height,
          );
          _pending.clear();
          _working = false;
        });
      }
    } catch (e) {
      if (mounted) {
        setState(() => _working = false);
        showHSnack(context, 'Page could not render: $e', error: true);
      }
    }
  }

  Future<void> _save() {
    final snapshot = _copyPages(_all);
    final history = ref.read(pdfStudioHistoryProvider.notifier);
    if (mounted) setState(() => _pendingWrites++);
    final path = widget.file.editStateJsonPath;
    final task = (_writesByPath[path] ?? Future<void>.value()).then((_) async {
      try {
        await StudioPdfEngine.writeAnnotations(widget.file.editStateJsonPath, snapshot);
        await history.markEdited(widget.file.id);
        if (mounted) setState(() { _saveError = false; _hasSaved = true; });
      } catch (_) {
        if (mounted) setState(() => _saveError = true);
        rethrow;
      } finally {
        if (mounted) setState(() => _pendingWrites--);
      }
    });
    final settled = task.then<void>((_) {}, onError: (Object _, StackTrace __) {});
    _writesByPath[path] = settled;
    unawaited(settled.then((_) { if (identical(_writesByPath[path], settled)) _writesByPath.remove(path); }));
    return task;
  }

  Future<void> _persist() async {
    try {
      await _save();
    } catch (e) {
      if (mounted) {
        showHSnack(context, 'Could not save page edits. Your edits remain here; retry Save. $e', error: true);
      }
    }
  }

  Offset _normalized(Offset point, Size size) => Offset(
    (point.dx / size.width).clamp(0.0, 1.0).toDouble(),
    (point.dy / size.height).clamp(0.0, 1.0).toDouble(),
  );

  void _finishStroke() {
    if (_pending.isEmpty) return;
    if (_marks.length >= 100) {
      setState(() => _pending.clear());
      showHSnack(context, 'This page has reached the edit limit.', error: true);
      return;
    }
    setState(() {
      _checkpoint();
      _marks.add({
        'tool': _tool.name,
        'points': [
          for (final point in _pending) [point.dx, point.dy],
        ],
        'color': _color,
        'stroke': _stroke,
        'opacity': _opacity,
      });
      _pending.clear();
    });
    unawaited(_persist());
  }

  Future<void> _placeText(Offset point) async {
    final controller = TextEditingController();
    final value = await showDialog<String>(
      context: context,
      builder: (dialog) => AlertDialog(
        title: Text(
          _tool == _MarkTool.signature ? 'Typed signature' : 'Page text note',
        ),
        content: TextField(
          controller: controller,
          autofocus: true,
          maxLength: 90,
          decoration: const InputDecoration(hintText: 'Write on this page'),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialog),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(dialog, controller.text),
            child: const Text('Place'),
          ),
        ],
      ),
    );
    controller.dispose();
    if (value == null || value.trim().isEmpty || !mounted) return;
    if (_marks.length >= 100) {
      showHSnack(context, 'This page has reached the edit limit.', error: true);
      return;
    }
    setState(
      () { _checkpoint(); _marks.add({
        'tool': _tool.name,
        'points': [
          [point.dx, point.dy],
        ],
        'color': _color,
        'stroke': _stroke,
        'opacity': _opacity,
        'text': value.trim(),
      }); },
    );
    await _persist();
  }

  Future<void> _export() async {
    setState(() => _working = true);
    try {
      await _save();
      if (!mounted) return;
      final source = widget.file;
      final pages = [
        for (var index = 0; index < _total; index++)
          StudioPage(
            source.internalFilePath,
            index,
            annotations: _all['${index + 1}'] ?? const [],
          ),
      ];
      final name = source.displayName.replaceFirst(
        RegExp(r'\.pdf$', caseSensitive: false),
        ' annotated.pdf',
      );
      final output = await runStudioOperation(context, (operation) async {
        final path = await StudioPdfEngine.compose(pages);
        await operation.commit();
        return await ref
          .read(pdfStudioHistoryProvider.notifier)
          .importFile(
            path,
            originalFileName: name,
            sourceType: 'CREATED',
            operationBadge: 'EDITED',
          );
      });
      if (mounted) {
        final router = GoRouter.of(context);
        Navigator.of(context).pop();
        router.push('/pdf-studio/viewer/${output.id}');
      }
    } catch (e) {
      if (mounted) {
        showHSnack(context, isStudioCancellation(e) ? 'Cancelled. Your annotations are retained.' : 'Could not export annotated PDF: $e', error: !isStudioCancellation(e));
      }
    } finally {
      if (mounted) setState(() => _working = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final image = _image;
    final theme = Theme.of(context);
    final canvas = Expanded(
            child: _working
                ? const Center(child: CircularProgressIndicator())
                : image == null ? Center(child: TextButton(onPressed: _total > 0 ? _showPage : _load, child: const Text('Retry page')))
                : LayoutBuilder(
                    builder: (context, constraints) {
                      final width =
                          constraints.maxWidth <
                              constraints.maxHeight * image.width / image.height
                          ? constraints.maxWidth
                          : constraints.maxHeight * image.width / image.height;
                      final height = width * image.height / image.width;
                      final size = Size(width, height);
                      return Center(
                        child: SizedBox(
                          width: width,
                          height: height,
                          child: GestureDetector(
                            key: const ValueKey('annotation-canvas'),
                            dragStartBehavior: DragStartBehavior.down,
                            behavior: HitTestBehavior.opaque,
                            onPanStart:
                                (_tool == _MarkTool.text ||
                                    _tool == _MarkTool.signature ||
                                    _tool == _MarkTool.note)
                                ? null
                                : (d) {
                                    if (_tool == _MarkTool.select) {
                                      setState(() {
                                        _moveRecorded = false;
                                        _selectMark(
                                          _normalized(d.localPosition, size),
                                        );
                                        _dragPoint = _normalized(
                                          d.localPosition,
                                          size,
                                        );
                                      });
                                      return;
                                    }
                                    setState(
                                      () => _pending
                                        ..clear()
                                        ..add(
                                          _normalized(d.localPosition, size),
                                        ),
                                    );
                                  },
                            onPanUpdate:
                                (_tool == _MarkTool.text ||
                                    _tool == _MarkTool.signature ||
                                    _tool == _MarkTool.note)
                                ? null
                                : (d) {
                                    final point = _normalized(
                                      d.localPosition,
                                      size,
                                    );
                                    if (_tool == _MarkTool.select) {
                                      if (_selected != null &&
                                          _dragPoint != null) {
                                        final delta = point - _dragPoint!;
                                        setState(() {
                                          if (!_moveRecorded && delta.distance > 0) { _checkpoint(); _moveRecorded = true; }
                                          final mark =
                                              Map<String, dynamic>.from(
                                                _marks[_selected!],
                                              );
                                          mark['points'] = [
                                            for (final p
                                                in mark['points'] as List)
                                              [
                                                ((p[0] as num).toDouble() +
                                                        delta.dx)
                                                    .clamp(0.0, 1.0),
                                                ((p[1] as num).toDouble() +
                                                        delta.dy)
                                                    .clamp(0.0, 1.0),
                                              ],
                                          ];
                                          _marks[_selected!] = mark;
                                          _dragPoint = point;
                                        });
                                      }
                                      return;
                                    }
                                    setState(() {
                                      if (_tool == _MarkTool.rectangle ||
                                          _tool == _MarkTool.arrow ||
