                                          (_pending.isEmpty ||
                                              (point - _pending.last).distance >
                                                  .003)) {
                                        _pending.add(point);
                                      }
                                    });
                                  },
                            onPanEnd: (_) {
                              if (_tool == _MarkTool.select) {
                                unawaited(_persist());
