              ),
            ),
canvas];
    final controls = <Widget>[pager, _dock(), exportControl];
    return Scaffold(
      appBar: AppBar(
        title: Text('Annotate · ${widget.file.displayName}', maxLines: 1),
        actions: [
          IconButton(tooltip: 'Undo edit', onPressed: _ready && (_undo[_page]?.isNotEmpty ?? false) ? () => _history(false) : null, icon: const Icon(Icons.undo_rounded)),
          IconButton(tooltip: 'Redo edit', onPressed: _ready && (_redo[_page]?.isNotEmpty ?? false) ? () => _history(true) : null, icon: const Icon(Icons.redo_rounded)),
          if (_selected != null) IconButton(tooltip: 'Delete selected mark', onPressed: _ready ? _deleteSelected : null, icon: const Icon(Icons.delete_outline)),
          PopupMenuButton<String>(tooltip: 'Edit session options', enabled: _ready, onSelected: (_) => _discardSession(), itemBuilder: (_) => const [PopupMenuItem(value: 'discard', child: Text('Discard session edits'))]),
          IconButton(
            tooltip: 'Save edit layer',
            onPressed: !_ready
                ? null
                : () async {
                    try {
                      await _save();
                      if (context.mounted) showHSnack(context, 'Edits saved');
                    } catch (e) {
                      if (context.mounted) {
                        showHSnack(
                          context,
                          'Could not save edits: $e',
