import 'dart:async';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import '../data/studio_pdf_engine.dart';

bool isStudioCancellation(Object error) => error is PlatformException &&
    (error.code == 'studio_cancelled' || error.code == 'export_cancelled');

class StudioOperation {
  StudioOperation._(this.id, this._status);
  final String id;
  final ValueNotifier<String> _status;
  static const _channel = MethodChannel('com.hyzen.pharmd/studio_work');
  bool _committed = false, _stopping = false, _closed = false;
  void _setStatus(String text) { if (!_closed) _status.value = text; }
  Future<void> checkpoint() async {
    await _channel.invokeMethod<bool>('check', {'id': id});
  }
  /// Atomic cancellation boundary, immediately before durable saving or an OS handoff.
  Future<void> commit() async {
    if (_committed) return;
    final ok = await _channel.invokeMethod<bool>('commit', {'id': id});
    if (ok != true) throw PlatformException(code: 'studio_commit', message: 'Could not save this copy. Retry.');
    _committed = true; _setStatus('Saving your copy…');
  }
  Future<void> cancel() async {
    if (_committed || _stopping || _closed) return;
    _stopping = true; _setStatus('Stopping safely…');
    try {
      final accepted = await _channel.invokeMethod<bool>('cancel', {'id': id});
      if (accepted != true) { _committed = true; _setStatus('Finishing your copy…'); }
    } catch (_) {
      _stopping = false; _setStatus('Could not stop yet. Please retry.');
    }
  }
}

/// Keeps editor input in place until native work acknowledges cancellation.
/// Generated session files survive until saving finishes, then only that session is cleaned.
Future<T> runStudioOperation<T>(BuildContext context,
    Future<T> Function(StudioOperation operation) action, {String label = 'Preparing your copy…'}) async {
  final status = ValueNotifier('Starting…');
  final navigator = Navigator.of(context, rootNavigator: true);
  StudioOperation? operation;
  final route = DialogRoute<void>(context: context, barrierDismissible: false,
    builder: (_) => PopScope(canPop: false, child: AlertDialog(
      title: const Text('Working on your copy'),
      content: ValueListenableBuilder<String>(valueListenable: status, builder: (_, text, __) =>
        SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
          if (MediaQuery.disableAnimationsOf(context)) const Icon(Icons.hourglass_top_rounded) else const LinearProgressIndicator(), const SizedBox(height: 20),
          Semantics(liveRegion: true, child: Text(text)), const SizedBox(height: 8),
          const Text('Your original document is kept safe.'),
        ]))),
      actions: [ValueListenableBuilder<String>(valueListenable: status, builder: (_, __, ___) =>
        TextButton(onPressed: operation == null || operation!._committed || operation!._stopping ? null : operation!.cancel,
          child: Text(operation?._stopping == true ? 'Stopping…' : 'Cancel')))],
    )));
  unawaited(navigator.push(route));
  try {
    final id = await StudioOperation._channel.invokeMethod<String>('begin');
    if (id == null || id.isEmpty) throw PlatformException(code: 'studio_begin', message: 'Could not start this operation.');
    final active = StudioOperation._(id, status); operation = active; status.value = label;
    return await StudioPdfEngine.withJob(id, () => action(active));
  } finally {
    final active = operation;
    if (active != null) {
      active._closed = true;
      try { await StudioOperation._channel.invokeMethod<bool>('finish', {'id': active.id}); }
      catch (_) { /* Native abandoned-session cleanup retains a conservative cache grace period. */ }
    }
    if (route.isActive && navigator.mounted) navigator.removeRoute(route);
    // A removed route may finish its last frame before disposing its listeners.
    WidgetsBinding.instance.addPostFrameCallback((_) => status.dispose());
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../core/utils/media_upload.dart';
import '../../../core/widgets/common.dart';
import '../data/pdf_studio_repository.dart';
import '../data/studio_file_item.dart';
import '../data/studio_pdf_engine.dart';
import '../data/studio_text_export.dart';
import 'studio_operation.dart';

enum _Format {
  original,
  flat,
  layered,
  protected,
  compressed,
  ocrPdf,
  ocrText,
  text,
  md,
  docx,
  png,
  jpg,
}

enum _Destination { studio, device, share }

Future<void> showStudioExportSheet(
  BuildContext context,
  StudioFileItem file,
) async {
  final pdf = file.internalFilePath.toLowerCase().endsWith('.pdf');
  final notes = pdf
      ? await StudioPdfEngine.readAnnotations(file.editStateJsonPath)
      : <String, List<Map<String, dynamic>>>{};
  if (!context.mounted) return;
  final marks = notes.values.any((p) => p.isNotEmpty);
  final options = <(_Format, IconData, String)>[
    (
      _Format.original,
      Icons.file_present,
      pdf ? 'Original PDF' : 'Original file',
    ),
    if (pdf) ...[
      if (marks) ...[
        (
          _Format.layered,
          Icons.layers_outlined,
          'PDF with editable annotations',
        ),
        (_Format.flat, Icons.draw_rounded, 'Flattened PDF copy'),
      ],
      (_Format.protected, Icons.lock_outline, 'Password-protected PDF'),
      (_Format.compressed, Icons.compress_rounded, 'Smaller PDF'),
      (
        _Format.ocrPdf,
        Icons.document_scanner_outlined,
        'Make scanned PDF searchable · OCR',
      ),
      (
        _Format.ocrText,
        Icons.text_fields_rounded,
        'Recognize scanned text · OCR',
      ),
      (_Format.text, Icons.text_snippet_outlined, 'Extract text · TXT'),
      (_Format.md, Icons.notes_rounded, 'Extract text · Markdown'),
      (_Format.docx, Icons.description_outlined, 'Text document · DOCX'),
      (_Format.png, Icons.image_outlined, 'PNG pages · ZIP'),
      (_Format.jpg, Icons.photo_library_outlined, 'JPG pages · ZIP'),
    ],
  ];
  final format = await showModalBottomSheet<_Format>(
    context: context,
    showDragHandle: true,
    isScrollControlled: true,
    builder: (sheet) => SafeArea(
      child: SizedBox(
        height: MediaQuery.sizeOf(sheet).height * .75,
        child: ListView(
          children: [
            const ListTile(title: Text('Export document')),
            for (final option in options)
              ListTile(
                leading: Icon(option.$2),
                title: Text(option.$3),
                onTap: () => Navigator.pop(sheet, option.$1),
              ),
          ],
        ),
      ),
    ),
  );
  if (format == null || !context.mounted) return;
  String? password;
  var preset = 'balanced';
  if (format == _Format.protected) {
    password = await _password(context);
    if (password == null || !context.mounted) return;
  }
  if (format == _Format.compressed) {
    final chosen = await showDialog<String>(
      context: context,
      builder: (c) => SimpleDialog(
        title: const Text('PDF size'),
        children: [
          for (final choice in [
            ('small', 'Smallest file'),
            ('balanced', 'Balanced'),
            ('quality', 'Higher quality'),
          ])
            SimpleDialogOption(
              onPressed: () => Navigator.pop(c, choice.$1),
              child: Text(choice.$2),
            ),
        ],
      ),
    );
    if (chosen == null || !context.mounted) return;
    preset = chosen;
  }
  final destination = await showModalBottomSheet<_Destination>(
    context: context,
    showDragHandle: true,
    builder: (sheet) => SafeArea(
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          const ListTile(title: Text('Save your copy')),
          for (final choice in [
            if (format != _Format.png && format != _Format.jpg)
              (_Destination.studio, Icons.folder_outlined, 'PDF Studio'),
            (_Destination.device, Icons.save_alt, 'Save As on device'),
            (_Destination.share, Icons.share, 'Share with an app'),
          ])
            ListTile(
              leading: Icon(choice.$2),
              title: Text(choice.$3),
              onTap: () => Navigator.pop(sheet, choice.$1),
            ),
        ],
      ),
    ),
  );
  if (destination == null || !context.mounted) return;
  try {
    await runStudioOperation(context, (operation) async {
    var path = file.internalFilePath;
    var name = file.displayName;
    var mime = pdf ? 'application/pdf' : 'application/octet-stream';
    final stem = name.replaceFirst(RegExp(r'\.[^.]+$'), '');
    if (format == _Format.layered || format == _Format.flat) {
      final count = await StudioPdfEngine.pageCount(path);
      path = await StudioPdfEngine.compose([
        for (var i = 0; i < count; i++)
          StudioPage(
            file.internalFilePath,
            i,
            annotations: notes['${i + 1}'] ?? const [],
          ),
      ], flatten: format == _Format.flat);
      name = '${stem}_${format == _Format.flat ? 'flat' : 'annotated'}.pdf';
    } else if (format == _Format.protected) {
      path = await StudioPdfEngine.protect(path, password!);
      name = '${stem}_protected.pdf';
    } else if (format == _Format.compressed) {
      path = await StudioPdfEngine.compress(path, preset);
      name = '${stem}_optimized.pdf';
    } else if (format == _Format.ocrPdf || format == _Format.ocrText) {
      final result = await StudioPdfEngine.ocr(path);
      if (result.text.trim().isEmpty) {
        throw const FormatException('No readable Latin text was found.');
      }
      path = format == _Format.ocrPdf
          ? result.path
          : await StudioPdfEngine.textFile(result.text);
      name = '${stem}_ocr.${format == _Format.ocrPdf ? 'pdf' : 'txt'}';
      mime = format == _Format.ocrPdf ? 'application/pdf' : 'text/plain';
    } else if (format == _Format.text ||
        format == _Format.md ||
        format == _Format.docx) {
      final text = await extractStudioPdfText(path, checkpoint: operation.checkpoint);
      if (text.trim().isEmpty) {
        throw const FormatException('Use OCR for scanned pages.');
      }
      path = format == _Format.docx
          ? await StudioPdfEngine.textToDocx(text)
          : await StudioPdfEngine.textFile(text);
      name =
          '$stem.${format == _Format.docx
              ? 'docx'
              : format == _Format.md
              ? 'md'
              : 'txt'}';
      mime = format == _Format.docx
          ? 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
          : format == _Format.md
          ? 'text/markdown'
          : 'text/plain';
    } else if (format == _Format.png || format == _Format.jpg) {
      path = await StudioPdfEngine.pagesToImages(
        path,
        format == _Format.png ? 'png' : 'jpg',
      );
      name = '${stem}_pages.zip';
      mime = 'application/zip';
    }
    await operation.commit();
    if (!context.mounted) return;
    if (destination == _Destination.studio) {
      await ProviderScope.containerOf(context, listen: false)
          .read(pdfStudioHistoryProvider.notifier)
          .importFile(
            path,
            originalFileName: name,
            sourceType: 'CREATED',
            operationBadge: 'EXPORTED',
          );
      if (context.mounted) showHSnack(context, 'Saved in PDF Studio');
    } else {
      final ok = destination == _Destination.device
          ? await MediaUpload.exportDocument(path, name, mime)
          : await MediaUpload.shareDocument(path, name, mime);
      if (context.mounted) {
        showHSnack(context, ok ? 'Copy ready' : 'Export cancelled');
      }
    }
    });
  } catch (error) {
    if (context.mounted) {
      showHSnack(
        context,
        isStudioCancellation(error) ? 'Operation cancelled. Your original is retained.' : error is FormatException
            ? error.message
            : 'Could not export this document. Try a different option.',
        error: !isStudioCancellation(error),
      );
    }
  } finally {
    password = null;
  }
}

Future<String?> _password(BuildContext context) async {
  final password = TextEditingController();
  final confirm = TextEditingController();
  final key = GlobalKey<FormState>();
  final result = await showDialog<String>(
    context: context,
    builder: (c) => AlertDialog(
      title: const Text('Protect this PDF'),
      content: Form(
        key: key,
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            TextFormField(
              controller: password,
              obscureText: true,
              enableSuggestions: false,
              autocorrect: false,
              decoration: const InputDecoration(labelText: 'Password'),
              validator: (v) => (v?.length ?? 0) < 6
                  ? 'Use at least 6 characters'
                  : (v?.length ?? 0) > 128
                  ? 'Use up to 128 characters'
                  : null,
            ),
            const SizedBox(height: 12),
            TextFormField(
              controller: confirm,
              obscureText: true,
              enableSuggestions: false,
              autocorrect: false,
              decoration: const InputDecoration(labelText: 'Confirm password'),
              validator: (v) =>
                  v != password.text ? 'Passwords do not match' : null,
            ),
            const SizedBox(height: 12),
            const Text('Keep your password safe. It cannot be recovered.'),
          ],
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(c),
          child: const Text('Cancel'),
        ),
        FilledButton(
          onPressed: () {
            if (key.currentState!.validate()) Navigator.pop(c, password.text);
          },
          child: const Text('Continue'),
        ),
      ],
    ),
  );
  password.dispose();
  confirm.dispose();
  return result;
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

import '../../../core/utils/media_upload.dart';
import '../../../core/widgets/common.dart';
import '../data/pdf_studio_repository.dart';
import '../data/studio_file_item.dart';
import '../data/studio_pdf_engine.dart';
import 'studio_page_thumbnail.dart';
import 'page_grid.dart';
import 'studio_operation.dart';

enum StudioTool { open, merge, split, organize, images, document }

class StudioToolsScreen extends ConsumerStatefulWidget {
  const StudioToolsScreen({super.key, required this.tool, this.initialFile});
  final StudioTool tool;
  final StudioFileItem? initialFile;

  @override
  ConsumerState<StudioToolsScreen> createState() => _StudioToolsScreenState();
}

class _StudioToolsScreenState extends ConsumerState<StudioToolsScreen> {
  final _title = TextEditingController();
  final _text = TextEditingController();
  final _range = TextEditingController();
  final _sources = <PickedStudioFile>[];
  final _pages = <StudioPage>[];
  final _splitSelected = <int>{};
  bool _busy = false;

  String get _heading => switch (widget.tool) {
    StudioTool.open => 'Open PDF or document',
    StudioTool.merge => 'Merge PDFs',
    StudioTool.split => 'Split or extract pages',
    StudioTool.organize => 'Organize pages',
    StudioTool.images => 'Images to PDF',
    StudioTool.document => 'Document writer',
  };

  @override
  void initState() {
    super.initState();
    final file = widget.initialFile;
    if (file != null) {
      _title.text = file.displayName.replaceFirst(RegExp(r'\.[^.]+$'), ' copy');
      WidgetsBinding.instance.addPostFrameCallback(
        (_) => _work(() async {
          if (widget.tool == StudioTool.document) {
            final text = await StudioPdfEngine.readText(file.internalFilePath);
            if (mounted) _text.text = text;
          } else {
            await _addPaths([
              PickedStudioFile(file.displayName, file.internalFilePath),
            ]);
          }
        }),
      );
    }
  }

  @override
  void dispose() {
    _title.dispose();
    _text.dispose();
    _range.dispose();
    super.dispose();
  }

  Future<void> _work(Future<void> Function() action) async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      await action();
    } catch (e) {
      if (mounted) {
        showHSnack(
          context,
          isStudioCancellation(e) ? 'Cancelled. Your selected pages are retained.' : e is FormatException
              ? e.message
              : 'Could not complete this operation. Please retry.',
          error: !isStudioCancellation(e),
        );
      }
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _chooseHistory() async {
    final available = ref
        .read(pdfStudioHistoryProvider)
        .where((f) => f.internalFilePath.toLowerCase().endsWith('.pdf'))
        .toList();
    final selected = <String>{};
    final picked = await showModalBottomSheet<List<PickedStudioFile>>(
      context: context,
      isScrollControlled: true,
      showDragHandle: true,
      builder: (c) => StatefulBuilder(
        builder: (c, update) => SafeArea(
          child: SizedBox(
            height: MediaQuery.sizeOf(c).height * .7,
            child: Column(
              children: [
                const ListTile(title: Text('Choose from PDF Studio')),
                Expanded(
                  child: available.isEmpty
                      ? const Center(
                          child: Text('No PDFs in your workspace yet.'),
                        )
                      : ListView(
                          children: [
                            for (final file in available)
                              CheckboxListTile(
                                title: Text(file.displayName),
                                value: selected.contains(file.id),
                                onChanged: (v) => update(() {
                                  if (widget.tool != StudioTool.merge) {
                                    selected.clear();
                                  }
                                  if (v == true) {
                                    selected.add(file.id);
                                  } else {
                                    selected.remove(file.id);
                                  }
                                }),
                              ),
                          ],
                        ),
                ),
                Padding(
                  padding: const EdgeInsets.all(12),
                  child: FilledButton(
                    onPressed: selected.isEmpty
                        ? null
                        : () => Navigator.pop(c, [
                            for (final f in available)
                              if (selected.contains(f.id))
                                PickedStudioFile(
                                  f.displayName,
                                  f.internalFilePath,
                                ),
                          ]),
                    child: const Text('Use selected PDFs'),
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
    if (picked != null && mounted) await _work(() => _addPaths(picked));
  }

  Future<void> _pick() => _work(() async {
    final picked = await StudioPdfEngine.pickFiles();
    if (picked.isNotEmpty) await _addPaths(picked);
  });

  Future<void> _addPaths(
    List<PickedStudioFile> picked, {
    bool replace = false,
  }) async {
    if (!mounted) return;
    if (widget.tool == StudioTool.open) {
      final chosen = picked.first;
      final item = await ref
          .read(pdfStudioHistoryProvider.notifier)
          .importFile(chosen.path, originalFileName: chosen.name);
      if (mounted) _openSaved(item.id);
      return;
    }
    final candidates =
        (widget.tool == StudioTool.merge || widget.tool == StudioTool.images)
        ? (replace ? picked : [..._sources, ...picked])
        : [picked.first];
    final selected = {
      for (final file in candidates) file.path: file,
    }.values.toList();
    if (widget.tool == StudioTool.images) {
      if (selected.any(
        (f) => !RegExp(
          r'\.(jpe?g|png|webp)$',
          caseSensitive: false,
        ).hasMatch(f.name),
      )) {
        throw const FormatException('Select images only.');
      }
      setState(
        () => _sources
          ..clear()
          ..addAll(selected),
      );
      return;
    }
    if (selected.any((f) => !f.path.toLowerCase().endsWith('.pdf'))) {
      throw const FormatException('Select PDF files only.');
    }
    final pages = <StudioPage>[];
    for (final source in selected) {
      final count = await StudioPdfEngine.pageCount(source.path);
      if (count > 150 || count + pages.length > 150) {
        throw const FormatException('The maximum is 150 pages per operation.');
      }
      for (var index = 0; index < count; index++) {
        pages.add(StudioPage(source.path, index));
      }
    }
    if (mounted) {
      setState(() {
        _sources
          ..clear()
          ..addAll(selected);
        _pages
          ..clear()
          ..addAll(pages);
        _splitSelected.clear();
      });
    }
  }

  Future<StudioFileItem> _save(String path, String name, String badge) => ref
      .read(pdfStudioHistoryProvider.notifier)
      .importFile(
        path,
        originalFileName: name,
        sourceType: badge,
        operationBadge: badge,
      );

  Future<StudioFileItem> _finish(String path, String name, String badge, StudioOperation operation) async {
    final pdf = name.toLowerCase().endsWith('.pdf');
    final count = pdf ? await StudioPdfEngine.pageCount(path) : 0;
    if (pdf && count < 1) {
      throw const FormatException('The PDF could not be saved. Please retry.');
    }
    await operation.commit();
    final item = await _save(path, name, badge);
    if (pdf) {
      await ref
          .read(pdfStudioHistoryProvider.notifier)
          .updatePageCount(item.id, count);
    }
    return item;
  }

  Future<void> _offerSaved(StudioFileItem item) async {
    final pdf = item.internalFilePath.toLowerCase().endsWith('.pdf');
    if (!mounted) return;
    final destination = await showModalBottomSheet<String>(
      context: context,
      showDragHandle: true,
      builder: (c) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            ListTile(
              leading: const Icon(Icons.check_circle_rounded),
              title: Text('Saved: ${item.displayName}'),
              subtitle: const Text('Your new PDF is in Recent Files'),
            ),
            ListTile(
              leading: const Icon(Icons.save_alt_rounded),
              title: const Text('Save As on device'),
              onTap: () => Navigator.pop(c, 'device'),
            ),
            ListTile(
              leading: const Icon(Icons.ios_share_rounded),
              title: const Text('Share PDF'),
              onTap: () => Navigator.pop(c, 'share'),
            ),
            ListTile(
              leading: const Icon(Icons.menu_book_rounded),
              title: const Text('Open PDF'),
              onTap: () => Navigator.pop(c, 'open'),
            ),
          ],
        ),
      ),
    );
    if (!mounted) return;
    if (destination == 'device') {
      await MediaUpload.exportDocument(
        item.internalFilePath,
        item.displayName,
        pdf ? 'application/pdf' : 'text/plain',
      );
    }
    if (destination == 'share') {
      await MediaUpload.shareDocument(
        item.internalFilePath,
        item.displayName,
        pdf ? 'application/pdf' : 'text/plain',
      );
    }
    if (mounted) _openSaved(item.id);
  }

  void _openSaved(String id) {
    final router = GoRouter.of(context);
    Navigator.of(context).pop();
    router.push('/pdf-studio/viewer/$id');
  }

  List<int> _parseRange(String input, int count) {
    final result = <int>{};
    for (final part in input.split(',')) {
      final match = RegExp(r'^\s*(\d+)\s*(?:-\s*(\d+)\s*)?$').firstMatch(part);
      if (match == null) {
        throw const FormatException('Use page numbers such as 1-3, 5, 8-10.');
      }
      final first = int.parse(match.group(1)!);
      final last = int.tryParse(match.group(2) ?? '') ?? first;
      if (first < 1 || last > count || last < first) {
        throw const FormatException('Page range is outside this PDF.');
      }
      for (var page = first; page <= last; page++) {
        result.add(page - 1);
      }
    }
    return result.toList()..sort();
  }

  Future<void> _create() => _work(() async {
    if (widget.tool == StudioTool.open) { await _pick(); return; }
    final name = _title.text.trim().isEmpty ? 'Studio document' : _title.text.trim();
    final item = await runStudioOperation(context, (operation) async {
      switch (widget.tool) {
        case StudioTool.open: throw StateError('Choose a creation tool.');
        case StudioTool.merge:
          if (_sources.length < 2) throw const FormatException('Select at least two PDFs.');
          return _finish(await StudioPdfEngine.compose(List.of(_pages)), '$name.pdf', 'MERGED', operation);
        case StudioTool.organize:
          if (_pages.isEmpty) throw const FormatException('Select pages first.');
          return _finish(await StudioPdfEngine.compose(List.of(_pages)), '$name.pdf', 'EDITED', operation);
        case StudioTool.split:
          if (_pages.isEmpty) throw const FormatException('Select a PDF first.');
          final selected = _splitSelected.isEmpty ? _parseRange(_range.text, _pages.length) : (_splitSelected.toList()..sort());
          return _finish(await StudioPdfEngine.compose([for (final i in selected) _pages[i]]), '$name.pdf', 'SPLIT', operation);
        case StudioTool.images:
          if (_sources.isEmpty) throw const FormatException('Choose images first.');
          return _finish(await StudioPdfEngine.imagesToPdf([for (final file in _sources) file.path]), '$name.pdf', 'CREATED', operation);
        case StudioTool.document:
          if (_text.text.trim().isEmpty) throw const FormatException('Write some text first.');
          return _finish(await StudioPdfEngine.textFile(_text.text), '$name.txt', 'CREATED', operation);
      }
    });
    if (mounted) await _offerSaved(item);
  });

  Future<void> _addSource() async {
    final choice = await showModalBottomSheet<String>(
      context: context,
      showDragHandle: true,
      builder: (c) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const ListTile(title: Text('Add PDFs')),
            ListTile(
              leading: const Icon(Icons.history_rounded),
              title: const Text('Recent files'),
              onTap: () => Navigator.pop(c, 'recent'),
            ),
            ListTile(
              leading: const Icon(Icons.folder_open_rounded),
              title: const Text('From device'),
              onTap: () => Navigator.pop(c, 'device'),
            ),
          ],
        ),
      ),
    );
    if (!mounted) return;
    if (choice == 'recent') await _chooseHistory();
    if (choice == 'device') await _pick();
  }

  void _movePage(int from, int to) {
    setState(() {
      final selectedIds = {for (final i in _splitSelected) _pages[i].id};
      final page = _pages.removeAt(from);
      _pages.insert(to, page);
      _splitSelected
        ..clear()
        ..addAll([
          for (var i = 0; i < _pages.length; i++)
            if (selectedIds.contains(_pages[i].id)) i,
        ]);
    });
  }

  @override
  Widget build(BuildContext context) {
    final split = widget.tool == StudioTool.split;
    final merge = widget.tool == StudioTool.merge;
    final organize = widget.tool == StudioTool.organize;
    final canSave =
        !_busy &&
        (split
            ? _splitSelected.isNotEmpty || _range.text.trim().isNotEmpty
            : merge
            ? _sources.length >= 2
            : widget.tool == StudioTool.document
            ? _text.text.trim().isNotEmpty
            : _pages.isNotEmpty || _sources.isNotEmpty);
    return PopScope(
      canPop: !_busy,
      child: Scaffold(
        appBar: AppBar(
          title: Text(split ? '${_splitSelected.length} Selected' : _heading),
          actions: [
            if (split && _pages.isNotEmpty)
              TextButton(
                onPressed: _busy
                    ? null
                    : () => setState(() {
                        if (_splitSelected.length == _pages.length) {
                          _splitSelected.clear();
                        } else {
                          _splitSelected.addAll(
                            List.generate(_pages.length, (i) => i),
                          );
                        }
                      }),
                child: Text(
                  _splitSelected.length == _pages.length
                      ? 'Clear'
                      : 'Select all',
                ),
              ),
            if (merge || _pages.isEmpty)
              IconButton(
                tooltip: 'Add PDFs',
                onPressed: _busy ? null : _addSource,
                icon: const Icon(Icons.add_rounded),
              ),
          ],
        ),
        body: Column(
          children: [
            if (_busy) const LinearProgressIndicator(minHeight: 2),
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 6, 16, 8),
              child: TextField(
                controller: _title,
                maxLength: 100,
                decoration: const InputDecoration(
                  labelText: 'PDF name',
                  counterText: '',
                  isDense: true,
                ),
              ),
            ),
            if (merge)
              Padding(
                padding: const EdgeInsets.symmetric(
                  horizontal: 16,
                  vertical: 4,
                ),
                child: Row(
                  children: [
                    Expanded(
                      child: Text(
                        '${_sources.length} PDFs · ${_pages.length} pages',
                      ),
                    ),
                    TextButton.icon(
                      onPressed: _busy ? null : _addSource,
                      icon: const Icon(Icons.add_rounded),
                      label: const Text('Add PDFs'),
                    ),
                  ],
                ),
              ),
            if (split && _pages.isNotEmpty)
              Padding(
                padding: const EdgeInsets.symmetric(horizontal: 16),
                child: TextField(
                  controller: _range,
                  onChanged: (_) => setState(() {}),
                  decoration: const InputDecoration(
                    hintText: 'Optional page range, e.g. 1-3, 5',
                    isDense: true,
                  ),
                ),
              ),
            Expanded(
              child: merge
                  ? _sources.isEmpty
                        ? _empty()
                        : ReorderableListView.builder(
                            padding: const EdgeInsets.all(16),
                            itemCount: _sources.length,
                            onReorder: (from, to) => setState(() {
                              if (to > from) to--;
                              final moved = _sources.removeAt(from);
                              _sources.insert(to, moved);
                              final groups = {
                                for (final f in _sources)
                                  f.path: _pages
                                      .where((p) => p.path == f.path)
                                      .toList(),
                              };
                              _pages
                                ..clear()
                                ..addAll([
                                  for (final f in _sources) ...?groups[f.path],
                                ]);
                            }),
                            itemBuilder: (_, i) => Card(
                              key: ValueKey('${_sources[i].path}-$i'),
                              margin: const EdgeInsets.only(bottom: 10),
                              child: ListTile(
                                leading: const Icon(
                                  Icons.picture_as_pdf_rounded,
                                ),
                                title: Text(_sources[i].name, maxLines: 2),
                                subtitle: const Text(
                                  'Hold to change merge order',
                                ),
                                trailing: IconButton(
                                  tooltip: 'Remove file',
                                  icon: const Icon(Icons.close_rounded),
                                  onPressed: _busy
                                      ? null
                                      : () => _work(() async {
                                          final next = [..._sources]
                                            ..removeAt(i);
                                          if (next.isEmpty) {
                                            setState(() {
                                              _sources.clear();
                                              _pages.clear();
                                            });
                                          } else {
                                            await _addPaths(
                                              next,
                                              replace: true,
                                            );
                                          }
                                        }),
                                ),
                              ),
                            ),
                          )
                  : widget.tool == StudioTool.document
                  ? Padding(
                      padding: const EdgeInsets.all(16),
                      child: TextField(
                        controller: _text,
                        onChanged: (_) => setState(() {}),
                        expands: true,
                        maxLines: null,
                        minLines: null,
                        decoration: const InputDecoration(
                          hintText: 'Write your document',
                        ),
                      ),
                    )
                  : _pages.isEmpty
                  ? _empty()
                  : PageGrid(
                      count: _pages.length,
                      identity: (i) => _pages[i].id,
                      image: (i) => _pages[i].blank
                          ? const Icon(Icons.description_outlined)
                          : StudioPageThumbnail(page: _pages[i]),
                      selected: _splitSelected,
                      onSelect: split
                          ? (i) => setState(() {
                              if (!_splitSelected.add(i)) {
                                _splitSelected.remove(i);
                              }
                            })
                          : null,
                      onMove: _busy ? (_, __) {} : _movePage,
                      onRotate: organize
                          ? (i) =>
                                setState(() => _pages[i] = _pages[i].rotate())
                          : null,
                      onRemove: organize
                          ? (i) => setState(() => _pages.removeAt(i))
                          : null,
                    ),
            ),
          ],
        ),
        bottomNavigationBar: SafeArea(
          top: false,
          child: Padding(
            padding: const EdgeInsets.fromLTRB(16, 8, 16, 12),
            child: FilledButton.icon(
              key: const ValueKey('save-page-operation'),
              onPressed: canSave ? _create : null,
              icon: const Icon(Icons.save_alt_rounded, size: 20),
              label: Text(
                split
                    ? 'Extract & save PDF'
                    : merge
                    ? 'Merge & save PDF'
                    : 'Save PDF',
              ),
            ),
          ),
        ),
      ),
    );
  }

  Widget _empty() => Center(
    child: FilledButton.tonalIcon(
      onPressed: _busy ? null : _addSource,
      icon: const Icon(Icons.folder_open_rounded),
      label: const Text('Choose PDF'),
    ),
  );
}

