import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import '../../../core/widgets/common.dart';
import '../data/pdf_studio_repository.dart';
import '../data/studio_pdf_engine.dart';
import 'studio_operation.dart';

class _Block {
  _Block(this.type, {String text = '', this.path = ''})
    : text = TextEditingController(text: text);
  final String type;
  final TextEditingController text;
  final String path;
  bool bold = false, italic = false, underline = false;
  String align = 'left';
  Map<String, Object> toMap() => {
    'type': type,
    'text': text.text,
    'path': path,
    'bold': bold,
    'italic': italic,
    'underline': underline,
    'align': align,
  };
}

class RichDocumentScreen extends ConsumerStatefulWidget {
  const RichDocumentScreen({super.key, this.template});
  final String? template;
  @override
  ConsumerState<RichDocumentScreen> createState() => _RichDocumentScreenState();
}

class _RichDocumentScreenState extends ConsumerState<RichDocumentScreen> {
  final _title = TextEditingController(text: 'My document');
  final _blocks = <_Block>[_Block('heading'), _Block('paragraph')];
  bool _busy = false;
  @override
  void initState() {
    super.initState();
    final template = widget.template;
    if (template != null) {
      for (final block in _blocks) {
        block.text.dispose();
      }
      _title.text = template;
      _blocks
        ..clear()
        ..addAll(
          template == 'Revision checklist'
              ? [
                  _Block('heading', text: 'Revision checklist'),
                  _Block(
                    'list',
                    text:
                        'Review key concepts\nPractise questions\nRevisit difficult topics',
                  ),
                ]
              : [
                  _Block('heading', text: 'Study notes'),
                  _Block('heading', text: 'Learning objectives'),
                  _Block('list'),
                  _Block('heading', text: 'Key concepts'),
                  _Block('paragraph'),
                  _Block('heading', text: 'Revision questions'),
                  _Block('list'),
                ],
        );
    }
  }

  @override
  void dispose() {
    _title.dispose();
    for (final b in _blocks) {
      b.text.dispose();
    }
    super.dispose();
  }

  Future<void> _image() async {
    try {
      final files = await StudioPdfEngine.pickFiles();
      final images = files.where(
        (f) => RegExp(
          r'\.(png|jpe?g|webp)$',
          caseSensitive: false,
        ).hasMatch(f.name),
      );
      if (!mounted) return;
      setState(
        () => _blocks.addAll(
          images
              .take(10)
              .map((f) => _Block('image', path: f.path, text: f.name)),
        ),
      );
    } catch (_) {
      if (mounted) {
        showHSnack(context, 'Could not select an image.', error: true);
      }
    }
  }

  Future<void> _save(String format) async {
    if (_busy) return;
    if (!_blocks.any(
      (b) => b.type == 'image' || b.text.text.trim().isNotEmpty,
    )) {
      showHSnack(context, 'Write something first.', error: true);
      return;
    }
    setState(() => _busy = true);
    try {
      final blocks = _blocks.map((b) => b.toMap()).toList();
      final name = _title.text.trim().isEmpty ? 'Document' : _title.text.trim();
      final file = await runStudioOperation(context, (operation) async {
        final path = await StudioPdfEngine.richDocument(blocks, format);
        await operation.commit();
        return await ref
          .read(pdfStudioHistoryProvider.notifier)
          .importFile(
            path,
            originalFileName: '$name.$format',
            sourceType: 'CREATED',
            operationBadge: 'CREATED',
          );
      });
      if (!mounted) return;
      final router = GoRouter.of(context);
      Navigator.pop(context);
      router.push('/pdf-studio/viewer/${file.id}');
    } catch (error) {
      if (mounted) {
        showHSnack(
          context,
          isStudioCancellation(error) ? 'Cancelled. Your document is still here.' : 'Could not save your document. Try again.',
          error: !isStudioCancellation(error),
        );
      }
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: const Text('Document writer')),
    body: ReorderableListView(
      padding: const EdgeInsets.all(20),
      header: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          TextField(
            controller: _title,
            maxLength: 100,
            decoration: const InputDecoration(labelText: 'Document name'),
          ),
          Wrap(
            spacing: 6,
            runSpacing: 6,
            children: [
              for (final option in [
                ('paragraph', 'Paragraph'),
                ('heading', 'Heading'),
                ('list', 'List'),
                ('table', 'Table'),
              ])
                ActionChip(
                  label: Text(option.$2),
                  onPressed: _busy || _blocks.length >= 100
                      ? null
                      : () => setState(() => _blocks.add(_Block(option.$1))),
                ),
              ActionChip(
                label: const Text('Image'),
                avatar: const Icon(Icons.image_outlined),
                onPressed: _busy ? null : _image,
              ),
            ],
          ),
          const SizedBox(height: 16),
          if (_busy) const LinearProgressIndicator(),
        ],
      ),
      footer: Padding(
        padding: const EdgeInsets.symmetric(vertical: 16),
        child: Wrap(
          spacing: 10,
          runSpacing: 8,
          children: [
            FilledButton.icon(
              onPressed: _busy ? null : () => _save('pdf'),
              icon: const Icon(Icons.picture_as_pdf),
              label: const Text('Save PDF'),
            ),
            OutlinedButton.icon(
              onPressed: _busy ? null : () => _save('docx'),
              icon: const Icon(Icons.description_outlined),
              label: const Text('Save Word document'),
            ),
          ],
        ),
      ),
      onReorder: (from, to) => setState(() {
        final moved = _blocks.removeAt(from);
        _blocks.insert(to > from ? to - 1 : to, moved);
      }),
      children: [
        for (final block in _blocks)
          Card(
            key: ObjectKey(block),
            child: Padding(
              padding: const EdgeInsets.all(12),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Row(
                    children: [
                      Expanded(
                        child: Text(
                          block.type == 'image'
                              ? 'Image'
                              : block.type[0].toUpperCase() +
                                    block.type.substring(1),
                        ),
                      ),
                      IconButton(
                        tooltip: 'Remove block',
                        onPressed: _busy
                            ? null
                            : () => setState(() {
                                _blocks.remove(block);
                                block.text.dispose();
                              }),
                        icon: const Icon(Icons.close_rounded),
                      ),
                      const Icon(Icons.drag_handle),
                    ],
                  ),
                  if (block.type != 'image') ...[
                    Wrap(
                      spacing: 4,
                      children: [
                        IconButton(
                          tooltip: 'Bold',
                          isSelected: block.bold,
                          onPressed: () =>
                              setState(() => block.bold = !block.bold),
                          icon: const Icon(Icons.format_bold),
                        ),
                        IconButton(
                          tooltip: 'Italic',
                          isSelected: block.italic,
                          onPressed: () =>
                              setState(() => block.italic = !block.italic),
                          icon: const Icon(Icons.format_italic),
                        ),
                        IconButton(
                          tooltip: 'Underline',
                          isSelected: block.underline,
                          onPressed: () => setState(
                            () => block.underline = !block.underline,
                          ),
                          icon: const Icon(Icons.format_underline),
                        ),
                        for (final align in [
                          ('left', Icons.format_align_left),
                          ('center', Icons.format_align_center),
                          ('right', Icons.format_align_right),
                        ])
                          IconButton(
                            tooltip: 'Align ${align.$1}',
                            isSelected: block.align == align.$1,
                            onPressed: () =>
                                setState(() => block.align = align.$1),
                            icon: Icon(align.$2),
                          ),
                      ],
                    ),
                    TextField(
                      controller: block.text,
                      minLines: block.type == 'heading' ? 1 : 3,
                      maxLines: 12,
                      maxLength: 20000,
                      textAlign: block.align == 'center'
                          ? TextAlign.center
                          : block.align == 'right'
                          ? TextAlign.right
                          : TextAlign.left,
                      style: TextStyle(
                        fontWeight: block.bold || block.type == 'heading'
                            ? FontWeight.bold
                            : FontWeight.normal,
                        fontStyle: block.italic
                            ? FontStyle.italic
                            : FontStyle.normal,
                        decoration: block.underline
                            ? TextDecoration.underline
                            : TextDecoration.none,
                      ),
                      decoration: InputDecoration(
                        hintText: block.type == 'table'
                            ? 'Medicine | Dose\nExample | 5 mg'
                            : 'Write here…',
                        helperText: block.type == 'table'
                            ? 'One row per line. Separate cells with |.'
                            : null,
                      ),
                    ),
                  ] else
                    ListTile(
                      leading: const Icon(Icons.image_outlined),
                      title: Text(
                        block.text.text,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                      ),
                    ),
                ],
              ),
            ),
          ),
      ],
    ),
  );
}

test/studio_operation_test.dart:
import 'dart:async';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:hyzen_pharmd/features/pdf_studio/data/studio_pdf_engine.dart';
import 'package:hyzen_pharmd/features/pdf_studio/presentation/studio_operation.dart';
import 'package:hyzen_pharmd/features/pdf_studio/presentation/rich_document_screen.dart';

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();
  const control = MethodChannel('com.hyzen.pharmd/studio_work');
  const pdf = MethodChannel('com.hyzen.pharmd/pdf_studio');
  final messenger = TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger;
  late List<String> events;
  late List<MethodCall> methods;
  late bool cancelled;
  late bool committed;
  Completer<void>? rendering, saving;
  setUp(() {
    events = []; methods = []; cancelled = false; committed = false; rendering = null; saving = null;
    messenger.setMockMethodCallHandler(control, (call) async {
      events.add(call.method);
      if (call.method == 'begin') return 'fixture-job';
      if (call.method == 'cancel') { if (committed) return false; cancelled = true; return true; }
      if (call.method == 'check' || call.method == 'commit') {
        if (cancelled) throw PlatformException(code: 'studio_cancelled');
        if (call.method == 'commit') committed = true;
      }
      return true;
    });
    messenger.setMockMethodCallHandler(pdf, (call) async {
      methods.add(call); events.add(call.method);
      await rendering?.future;
      if (cancelled) throw PlatformException(code: 'studio_cancelled');
      return call.method == 'pageCount' ? 2 : '/generated/result.pdf';
    });
  });
  tearDown(() {
    messenger.setMockMethodCallHandler(control, null); messenger.setMockMethodCallHandler(pdf, null);
  });
  test('operation identity follows async transforms and stays out of other callers', () async {
    await StudioPdfEngine.withJob('a', () async {
      await StudioPdfEngine.compose([StudioPage('/original.pdf', 0)]);
      await Future<void>.value();
      await StudioPdfEngine.protect('/generated/result.pdf', 'secret8');
    });
    await StudioPdfEngine.pageCount('/original.pdf');
    expect(methods[0].arguments['studioJob'], 'a'); expect(methods[1].arguments['studioJob'], 'a');
    expect(methods[2].arguments.containsKey('studioJob'), isFalse);
  });
  Future<void> open(WidgetTester tester, Future<void> Function(BuildContext) action) async {
    await tester.pumpWidget(MaterialApp(home: Builder(builder: (context) => Scaffold(body:
      TextButton(onPressed: () => action(context), child: const Text('Start'))))));
    await tester.tap(find.text('Start')); await tester.pump(); await tester.pump(const Duration(milliseconds: 200));
  }
  testWidgets('cancel waits for native ACK, prevents save, releases only after worker returns', (tester) async {
    rendering = Completer<void>(); Object? failure; var writes = 0;
    await open(tester, (context) async {
      try { await runStudioOperation(context, (operation) async {
        await StudioPdfEngine.compose([StudioPage('/original.pdf', 0)]);
        await operation.commit(); writes++;
      }); } catch (error) { failure = error; }
    });
    await tester.tap(find.text('Cancel')); await tester.pump();
    expect(find.text('Stopping safely…'), findsOneWidget); expect(events, isNot(contains('finish')));
    await tester.binding.handlePopRoute(); await tester.pump(); expect(find.text('Working on your copy'), findsOneWidget);
    rendering!.complete(); await tester.pumpAndSettle();
    expect(isStudioCancellation(failure!), isTrue); expect(writes, 0); expect(events.last, 'finish');
    expect(find.text('Start'), findsOneWidget); expect(find.text('Working on your copy'), findsNothing);
  });
  testWidgets('commit disables cancellation and preserves generated files until durable copy ACK', (tester) async {
    saving = Completer<void>(); var done = false;
    await open(tester, (context) async { await runStudioOperation(context, (operation) async {
      await StudioPdfEngine.compress('/original.pdf', 'small'); await operation.commit();
      await saving!.future; events.add('durable-copy');
    }); done = true; });
    expect(find.text('Saving your copy…'), findsOneWidget);
    expect(tester.widget<TextButton>(find.widgetWithText(TextButton, 'Cancel')).onPressed, isNull);
    expect(events, isNot(contains('finish'))); expect(done, isFalse);
    saving!.complete(); await tester.pumpAndSettle();
    expect(events.indexOf('durable-copy'), lessThan(events.indexOf('finish'))); expect(done, isTrue);
  });
  testWidgets('cancel between transforms is checked before any save', (tester) async {
    final gate = Completer<void>(); Object? failure;
    await open(tester, (context) async { try { await runStudioOperation(context, (operation) async {
      await StudioPdfEngine.protect('/original.pdf', 'secret8'); await gate.future; await operation.commit();
      events.add('must-not-save');
    }); } catch (error) { failure = error; } });
    await tester.tap(find.text('Cancel')); await tester.pump(); gate.complete(); await tester.pumpAndSettle();
    expect(isStudioCancellation(failure!), isTrue); expect(events, isNot(contains('must-not-save'))); expect(events.last, 'finish');
  });
  testWidgets('failed destination still cleans session and retains editor route', (tester) async {
    Object? failure;
    await open(tester, (context) async { try { await runStudioOperation(context, (operation) async {
      await StudioPdfEngine.textToDocx('notes'); await operation.commit(); throw const FormatException('Disk full');
    }); } catch (error) { failure = error; } });
    await tester.pumpAndSettle(); expect(failure, isA<FormatException>()); expect(events.last, 'finish'); expect(find.text('Start'), findsOneWidget);
  });
  testWidgets('late cancel reply cannot update a disposed operation dialog', (tester) async {
    final ready = Completer<void>();
    final cancelReply = Completer<bool>();
    messenger.setMockMethodCallHandler(control, (call) async {
      if (call.method == 'begin') return 'late-reply';
      if (call.method == 'cancel') return cancelReply.future;
      return true;
    });
    await open(tester, (context) async {
      await runStudioOperation(context, (operation) async {
        await ready.future;
        await operation.commit();
      });
    });
    await tester.tap(find.text('Cancel')); await tester.pump();
    ready.complete(); await tester.pumpAndSettle();
    expect(find.text('Working on your copy'), findsNothing);
    cancelReply.complete(false); await tester.pumpAndSettle();
    expect(tester.takeException(), isNull);
  });
  testWidgets('large text and reduced motion keep cancellation available in landscape', (tester) async {
    final ready = Completer<void>();
    tester.view.physicalSize = const Size(640, 320); tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize); addTearDown(tester.view.resetDevicePixelRatio);
    await tester.pumpWidget(MaterialApp(builder: (context, child) => MediaQuery(
      data: MediaQuery.of(context).copyWith(disableAnimations: true, textScaler: const TextScaler.linear(1.8)), child: child!),
      home: Builder(builder: (context) => Scaffold(body: TextButton(onPressed: () async {
        await runStudioOperation(context, (_) => ready.future);
      }, child: const Text('Start'))))));
    await tester.tap(find.text('Start')); await tester.pump(); await tester.pump(const Duration(milliseconds: 200));
    expect(find.byType(LinearProgressIndicator), findsNothing);
    expect(tester.widget<TextButton>(find.widgetWithText(TextButton, 'Cancel')).onPressed, isNotNull);
    expect(tester.takeException(), isNull);
    ready.complete(); await tester.pumpAndSettle();
  });
  testWidgets('document writer retains its actual blocks when native conversion is cancelled', (tester) async {
    rendering = Completer<void>();
    await tester.pumpWidget(const ProviderScope(child: MaterialApp(home: RichDocumentScreen(template: 'Revision checklist'))));
    await tester.pumpAndSettle();
    await tester.scrollUntilVisible(find.text('Save PDF'), 300, scrollable: find.byType(Scrollable).first);
    await tester.tap(find.text('Save PDF')); await tester.pump(); await tester.pump(const Duration(milliseconds: 200));
    expect(methods.single.method, 'richDocument');
    expect(methods.single.arguments['blocks'][0]['text'], 'Revision checklist');
    await tester.tap(find.text('Cancel')); await tester.pump(); rendering!.complete(); await tester.pumpAndSettle();
    expect(events, isNot(contains('commit'))); expect(events.last, 'finish');
    expect(find.byType(RichDocumentScreen), findsOneWidget);
    expect(tester.widget<FilledButton>(find.byWidgetPredicate((widget) => widget is FilledButton).first).onPressed, isNotNull);
    expect(find.text('Cancelled. Your document is still here.'), findsOneWidget);
    expect(tester.takeException(), isNull);
  });
